import {session, policyPages, configVersions, rememberChoice, localGet, localSet, login, googleLogin, requestEmail, savePassword, finishPassword, verifyEmailAction, finishLogin, friendlyError, hasActionLink, logout} from './auth.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function legalFields(){return `<fieldset class="account-legal"><legend>Required legal acknowledgements</legend><label class="accept-all"><input type="checkbox" id="accept-all"><strong>Accept all of the below</strong></label>${policyPages.map(([key,path,title])=>`<label><input type="checkbox" name="legal" value="${key}" required><span>I accept the <a href="#${path}" target="_blank" rel="noopener">${title}</a>.</span></label>`).join('')}</fieldset>`;}
function passwordField(id,label,autocomplete='new-password'){return `<label class="account-field" for="${id}">${label}<span class="account-password"><input id="${id}" name="${id}" type="password" autocomplete="${autocomplete}" required ${autocomplete==='new-password'?'minlength="8"':''}><button type="button" data-password="${id}" aria-label="Show ${label.toLowerCase()}" aria-pressed="false">Show</button></span></label>`;}
export function renderAccount(route){
  const root=document.querySelector('#app');
  if(!session.ready){root.innerHTML='<main class="account-status" role="status" aria-busy="true">Checking your secure session…</main>';return;}
  const params=new URLSearchParams(location.search), action=route==='email-action'||hasActionLink();
  const verification=action&&params.get('mode')==='verifyEmail';
  const signup=route==='signup', recovery=route==='forgot-password';
  const gate=!!session.user?.emailVerified&&!action&&!signup&&!recovery;
  const title=verification?'Verify your email':action?'Set your password':recovery?'Reset your password':gate?'Your StrataX account':signup?'Create your account':'Welcome back';
  const caption=verification?'Confirm your email address to continue.':action?'Verify your email and save a password to continue.':recovery?'We will email a secure one-time recovery link.':gate?'Accept the current policies to open your workspace.':signup?'Verify your email with a secure one-time link, then set your password.':'Sign in to your StrataX workspace.';
  root.innerHTML=`<div class="account-page"><a class="account-home" href="#home"><img src="logo.png" alt="StrataX logo"><span>StrataX</span></a><main class="account-shell"><section class="account-brand"><a href="#home" aria-label="StrataX home"><img src="logo.png" alt="StrataX"></a><div class="eyebrow">TERRACODE ANALYTICS</div><h1>Subsurface interpretation,<br>with clarity.</h1><p>Bring your well data, project context and interpretation decisions into one organized workspace.</p><p class="account-shared">One TerraCode account. Your StrataX workspace.</p></section><section class="account-panel"><h2>${title}</h2><p class="account-caption">${caption}</p>${!action&&!recovery&&!gate?`<nav class="account-tabs" aria-label="Account access"><a href="#signin" ${!signup?'aria-current="page"':''}>Sign in</a><a href="#signup" ${signup?'aria-current="page"':''}>Create account</a></nav>`:''}<div id="account-notice" role="status" aria-live="polite">${session.error?`<p class="account-message error">${esc(session.error)}</p>`:''}</div><form id="account-form">${verification?'':gate?`<p class="account-identity">${esc(session.user.email)}</p>`:`${signup?'<label class="account-field" for="account-name">Full name<input id="account-name" name="name" autocomplete="name" required maxlength="120"></label>':''}<label class="account-field" for="account-email">${action?'Email for this link':'Email'}<input id="account-email" name="email" type="email" autocomplete="email" value="${action?esc(localGet('stratax.emailAddress')||''):''}" required></label>${action?passwordField('account-password','New password')+passwordField('account-confirm','Confirm new password')+'<p class="account-hint">At least eight characters with uppercase, lowercase, a number and a special character.</p>':!signup&&!recovery?passwordField('account-password','Password','current-password')+'<a class="account-forgot" href="#forgot-password">Forgot password?</a>':''}`}${!verification&&!recovery?`<label class="account-remember"><input type="checkbox" id="account-remember" ${rememberChoice()?'checked':''}><span>Keep me signed in for 30 days<small>Use only on a device you trust. You can sign out at any time.</small></span></label>${legalFields()}`:''}${action&&!verification?'<p class="account-hint">This password applies to your shared TerraCode account, including G-RES.</p>':''}<button class="account-primary" type="submit">${verification?'Verify email':action?'Save password':recovery?'Send recovery link':gate?'Accept and continue':signup?'Send one-time link':'Sign in'}</button>${!action&&!recovery&&!gate?'<button class="account-google" type="button" id="account-google"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M22.56 12.25c0-.73-.06-1.42-.19-2.09H12v3.96h5.92a5.06 5.06 0 0 1-2.2 3.32v2.76h3.56c2.08-1.92 3.28-4.75 3.28-7.95Z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.56-2.76c-.98.66-2.24 1.06-3.72 1.06-2.87 0-5.3-1.94-6.17-4.54H2.15v2.84A11 11 0 0 0 12 23Z"/><path fill="#FBBC05" d="M5.83 14.1A6.6 6.6 0 0 1 5.48 12c0-.73.13-1.44.35-2.1V7.06H2.15A11 11 0 0 0 1 12c0 1.78.43 3.47 1.15 4.94l3.68-2.84Z"/><path fill="#EA4335" d="M12 5.36c1.62 0 3.07.56 4.21 1.64l3.15-3.15A10.6 10.6 0 0 0 12 1a11 11 0 0 0-9.85 6.06L5.83 9.9C6.7 7.3 9.13 5.36 12 5.36Z"/></svg>Continue with Google</button>':''}</form>${gate?'<button class="account-secondary" id="account-signout">Sign out</button>':''}${!verification?`<p class="account-switch">${recovery||action?'<a href="#signin">Back to sign in</a>':signup?'Already have an account? <a href="#signin">Sign in</a>':'New to StrataX? <a href="#signup">Create an account</a>'}</p>`:''}<p class="account-support">Need help? <a href="mailto:contact@terracodeanalytics.com">Contact support</a></p><p class="account-copyright">© ${new Date().getFullYear()} Terracode Analytics Limited</p></section></main></div>`;
  root.querySelectorAll('a[href^="#"]').forEach(link=>{link.href=location.pathname+link.getAttribute('href');});
  const form=document.querySelector('#account-form'), notice=document.querySelector('#account-notice');
  const show=(message,error=false)=>{notice.innerHTML=`<p class="account-message ${error?'error':'success'}">${esc(message)}</p>`;};
  const legal=()=>[...form.querySelectorAll('input[name=legal]')].every(b=>b.checked);
  const requireLegal=()=>{if(legal())return true;show('Read and accept all seven StrataX policies before continuing.',true);form.querySelector('input[name=legal]:not(:checked)')?.focus();return false;};
  const all=form.querySelector('#accept-all');
  if(all){all.onchange=()=>form.querySelectorAll('input[name=legal]').forEach(b=>b.checked=all.checked);form.querySelectorAll('input[name=legal]').forEach(b=>b.onchange=()=>{const boxes=[...form.querySelectorAll('input[name=legal]')];all.checked=boxes.every(b=>b.checked);all.indeterminate=boxes.some(b=>b.checked)&&!all.checked;});}
  form.querySelectorAll('[data-password]').forEach(button=>button.onclick=()=>{const input=document.getElementById(button.dataset.password),showing=input.type==='password';input.type=showing?'text':'password';button.textContent=showing?'Hide':'Show';button.setAttribute('aria-pressed',String(showing));button.setAttribute('aria-label',(showing?'Hide ':'Show ')+(button.dataset.password==='account-confirm'?'confirmed password':'password'));});
  let busy=false;
  const run=async operation=>{if(busy)return;busy=true;const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);form.setAttribute('aria-busy','true');try{await operation();}catch(error){show(friendlyError(error),true);if(error.code==='email_not_verified'){
    const button=document.createElement('button');button.type='button';button.className='account-secondary';button.textContent='Send verification email';button.onclick=()=>run(async()=>{await requestEmail(form.elements.email.value,'verification');show('If eligible, a verification email will arrive shortly.');});notice.append(button);
  }}finally{busy=false;buttons.forEach(b=>b.disabled=false);form.removeAttribute('aria-busy');}};
  form.onsubmit=event=>{event.preventDefault();run(async()=>{
    if(verification){await verifyEmailAction(params.get('oobCode'));show('Email verified. You can now sign in.');form.innerHTML='<a class="account-primary" href="#signin">Continue to sign in</a>';return;}
    if(!recovery&&!requireLegal())return;
    const email=form.elements.email?.value||'',remember=document.querySelector('#account-remember')?.checked||false;
    if(recovery){await requestEmail(email,'recovery');show('If this address has an account, a recovery link will arrive shortly.');return;}
    if(signup){localSet('stratax.emailName',form.elements.name.value.trim());await requestEmail(email,'signup',form.elements.name.value);show('If eligible, your setup link will arrive shortly. Open it to verify your email and create a password.');return;}
    if(action){const password=form.elements['account-password'].value,confirmation=form.elements['account-confirm'].value;if(!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/.test(password))throw new Error('Use at least eight characters with uppercase, lowercase, a number and a special character.');if(password!==confirmation)throw new Error('The passwords do not match.');if(session.setupUser)await finishPassword(password);else await savePassword(email,password,remember,location.href);const purpose=params.get('purpose')||localGet('stratax.emailPurpose');await finishLogin(purpose==='signup'?{display_name:localGet('stratax.emailName')||'',organization:''}:undefined);return;}
    if(!gate)await login(email,form.elements['account-password'].value,remember);
    await finishLogin();
  });};
  document.querySelector('#account-google')?.addEventListener('click',()=>run(async()=>{if(!requireLegal())return;await googleLogin(document.querySelector('#account-remember').checked);await finishLogin(signup?{display_name:form.elements.name.value.trim(),organization:''}:undefined);}));
  document.querySelector('#account-signout')?.addEventListener('click',()=>run(logout));
}
